from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    def modes(values):
        return [Counter(v).most_common(1)[0][0] for v in values]

    row_modes = modes(grid)
    col_modes = modes([[grid[r][c] for r in range(h)] for c in range(w)])

    def minority_color(line_modes):
        counts = Counter(line_modes)
        return min(counts, key=counts.get)

    row_line_color = minority_color(row_modes)
    col_line_color = minority_color(col_modes)
    rows = [r for r, color in enumerate(row_modes) if color == row_line_color]
    cols = [c for c, color in enumerate(col_modes) if color == col_line_color]

    interior = [
        grid[r][c]
        for r in range(h) if r not in set(rows)
        for c in range(w) if c not in set(cols)
    ]
    background = Counter(interior).most_common(1)[0][0]

    result = []
    for i in range(len(rows) - 1):
        output_row = []
        for j in range(len(cols) - 1):
            corners = [
                grid[rows[i]][cols[j]],
                grid[rows[i]][cols[j + 1]],
                grid[rows[i + 1]][cols[j]],
                grid[rows[i + 1]][cols[j + 1]],
            ]
            output_row.append(corners[0] if len(set(corners)) == 1 else background)
        result.append(output_row)
    return result
